=================== demos/feature-normalization/equation.mlpl
# The applicative stone's equation (docs/research2.txt): feature-wise normalization over a fixed index space, z_i = (x_i − μ_i) / σ_i for i in Fin(3). Every position computes on its own; nothing is summed. The M face shows the same expression twice: Z ← (X − Μ) ÷ Σ, the array-only reading, and the tuple-typed reading X Μ Σ Z : Tuple[3], whose surface is the same and whose difference is what the language knows: arity 3, one index space, no length check at run time. Placeholder glyphs (see docs/plan.md).
include "../../lib/rosetta/ir.mlpl";

def u:fn_equation() {
  "Build the feature-normalization record: two lines per face, every symbol, line and face documented for the page.";
  ir = u:rs_ir_new("feature-normalization", "Feature normalization: each of three features is centred by its mean and scaled by its spread, every position on its own.");
  ir = u:rs_ir_titled(ir, "Feature normalization")?;
  ir = u:rs_ir_face_doc(ir, "math", "The rule at one position, and the index space", "Line one is the scalar rule for one feature i. Line two says where i lives: the finite index set Fin(3), the three positions. The whole computation is that one rule applied at every position independently; no position needs another, so there is no sum.")?;
  ir = u:rs_ir_face_doc(ir, "m", "The same computation, with and without homogeneous tuples", "Line one: the array reading, every entry at once, no index. Line two: the tuple-typed reading, declaring X, Μ, Σ and Z as fixed 3-tuples. The expression does not change; what changes is what the language knows before running: arity three, one shared index space, a result of arity three, and no length mismatch possible at run time. Placeholder glyphs.")?;
  ir = u:rs_ir_face_doc(ir, "visual", "Three independent lanes, and the index space they share", "One lane per position: x and μ into −, then ÷ σ, into z; the lane being computed is lit. The right panel is the applicative view: each index maps to its triple, the same rule f is applied, and a z comes out; the lanes never touch.")?;
  ir = u:rs_ir_symbol_doc(ir, "z", "var", "normalized features", "The output: three numbers, each feature expressed in units of its own spread, zero at its mean.")?;
  ir = u:rs_ir_symbol_doc(ir, "i", "var", "position", "Which feature: 0, 1 or 2. The stone's time axis steps through the positions.")?;
  ir = u:rs_ir_symbol_doc(ir, "eq", "op", "definition", "Definition: the left side is computed from the right side.")?;
  ir = u:rs_ir_symbol_doc(ir, "lp", "punct", "open", "Open parenthesis: group the difference before dividing.")?;
  ir = u:rs_ir_symbol_doc(ir, "rp", "punct", "close", "Close parenthesis.")?;
  ir = u:rs_ir_symbol_doc(ir, "x", "var", "features", "The input: three raw feature values, here the RGB channels of a pixel, 120, 80 and 200.")?;
  ir = u:rs_ir_symbol_doc(ir, "sub", "op", "subtract", "Centre: take the feature's mean away, so zero means average.")?;
  ir = u:rs_ir_symbol_doc(ir, "mu", "param", "means", "The mean of each feature over the data it was measured on: the ImageNet channel means 123, 117, 104.")?;
  ir = u:rs_ir_symbol_doc(ir, "div", "op", "divide", "Scale: divide by the feature's spread, so one means one standard deviation. In the notation, ÷.")?;
  ir = u:rs_ir_symbol_doc(ir, "sigma", "param", "spreads", "The standard deviation of each feature: 58, 57, 57.")?;
  ir = u:rs_ir_symbol_doc(ir, "in", "op", "membership", "i ranges over the index set: it takes each of its values.")?;
  ir = u:rs_ir_symbol_doc(ir, "Fin", "hyper", "finite index type", "Fin(n) is the set of positions 0 to n−1. A fixed 3-tuple of numbers is the same thing as a function from Fin(3) to numbers: that is the Naperian (representable) view the tuple line on the M face makes explicit.")?;
  ir = u:rs_ir_symbol_doc(ir, "three", "hyper", "three", "How many features there are; the arity of every tuple here.")?;
  ir = u:rs_ir_symbol_doc(ir, "colon", "punct", "has type", "Declares the type of what is on its left.")?;
  ir = u:rs_ir_symbol_doc(ir, "tuple", "hyper", "fixed homogeneous tuple", "Tuple[3]: exactly three numbers, structurally, not a list that happens to have three. With it the language knows the arity and the shared index space before running; without it the same expression runs on arrays and checks the lengths at run time.")?;
  ir = u:rs_ir_symbol_doc(ir, "lb", "punct", "open bracket", "Open bracket of the tuple's arity.")?;
  ir = u:rs_ir_symbol_doc(ir, "rb", "punct", "close bracket", "Close bracket.")?;
  ir = u:rs_ir_line(ir, "math", "z:z|i:_i|eq:=|lp:(|x:~x|i:_i|sub:−|mu:μ|i:_i|rp:~)|div:/|sigma:σ|i:_i")?;
  ir = u:rs_ir_line(ir, "math", "i:i|in:∈|Fin:Fin|lp:~(|three:~3|rp:~)")?;
  ir = u:rs_ir_line(ir, "m", "z:Z|eq:←|lp:(|x:~X|sub:−|mu:Μ|rp:~)|div:÷|sigma:Σ")?;
  ir = u:rs_ir_line(ir, "m", "x:X|mu:Μ|sigma:Σ|z:Z|colon::|tuple:Tuple|lb:~[|three:~3|rb:~]")?;
  ir = u:rs_ir_line_doc(ir, "math", 0, "The rule at position i: subtract the mean of feature i from feature i, divide by its spread.")?;
  ir = u:rs_ir_line_doc(ir, "math", 1, "The index space: i is one of the three positions, and the rule holds at each of them independently.")?;
  ir = u:rs_ir_line_doc(ir, "m", 0, "Array reading: subtract the means from the features, divide by the spreads, all positions at once; the lengths must agree at run time.")?;
  ir = u:rs_ir_line_doc(ir, "m", 1, "Tuple reading: the same four names declared as fixed 3-tuples, so arity and the shared index space are known before running; the expression above is unchanged.")?;
  u:rs_ir_validate(ir)?;
  ok(ir)
}
=================== demos/feature-normalization/faces.mlpl
# Render the feature-normalization stone's Math and proposed-M faces to SVG and write them, with the equation record as JSON: fixtures/feature-normalization/faces/ by default, or the directory given as the script's argument. Both documents are also printed; the reg-rs baseline rosetta_feature_normalization_faces pins them.
include "../../lib/rosetta/faces.mlpl";
include "../../lib/rosetta/emit.mlpl";
include "equation.mlpl";

fn_dir = if gt(list_len(args()), 0) {
  unwrap(list_get(args(), 0))
} else {
  "fixtures/feature-normalization/faces"
};

ir = unwrap(u:fn_equation());
unwrap(make_dir(fn_dir));
math = unwrap(u:rs_face_svg(ir, "math"));
m = unwrap(u:rs_face_svg(ir, "m"));
unwrap(write_atomic(str_concat(fn_dir, "/math.svg"), math));
unwrap(write_atomic(str_concat(fn_dir, "/m.svg"), m));
unwrap(u:rs_write_json(str_concat(fn_dir, "/equation.json"), unwrap(u:rs_ir_export(ir))));
print("MATH");
print(math);
print("M (proposed)");
print(m);
str_concat("wrote ", fn_dir)
=================== demos/feature-normalization/fn.mlpl
# The applicative stone's computation: normalize three features with their means and spreads, one position at a time so the page can replay the lanes lighting up, and all at once with MLPL's elementwise ops, which the tests compare. u:fn_steps records, for t = 0..2, the position, the difference and the quotient at that position, and z filled in so far.
include "../../lib/rosetta/emit.mlpl";
include "equation.mlpl";

fn_x = [120, 80, 200];
fn_mu = [123, 117, 104];
fn_sigma = [58, 57, 57];

def u:fn_all() {
  "Every position at once: the array reading.";
  (fn_x - fn_mu) / fn_sigma
}

def u:fn_steps() {
  "One row per position t = 0..2: the position, x_t − μ_t, z_t, and z with positions up to t filled (zero after).";
  n = len(fn_x);
  z = u:fn_all();
  index = fill([0], 0);
  diffs = fill([0], 0);
  quots = fill([0], 0);
  filled = fill([0], 0);
  t = 0;
  while lt(t, n) {
    index = concat(index, t);
    diffs = concat(diffs, take(fn_x, 0, t) - take(fn_mu, 0, t));
    quots = concat(quots, take(z, 0, t));
    filled = concat(filled, z * lt(range(n), t + 1));
    t = t + 1
  };
  {n: n, x: fn_x, mu: fn_mu, sigma: fn_sigma, z: z, i: index, diff: diffs, quot: quots, filled: reshape(filled, [n, n])}
}

def u:fn_trace(rows, places) {
  "The trace record: the axis is the position (n steps), the constants are the features, the means and the spreads, the channels are the position, the difference (sub), the quotient (div) and z so far.";
  {schema: "sw-ml-study.rosetta.trace", version: 1, equation: "feature-normalization", axis: {name: "position", count: rows.n}, constants: {x: rows.x, mu: rows.mu, sigma: rows.sigma, three: rows.n}, channels: {i: rows.i, sub: u:rs_round(rows.diff, places), div: u:rs_round(rows.quot, places), z: u:rs_array_json(u:rs_round(rows.filled, places))}}
}
=================== demos/feature-normalization/scene.mlpl
# Build the Visual face of feature normalization from the committed trace and write it: fixtures/feature-normalization/scene.json by default, or the path given as the script's argument. The JSON written is also printed; the reg-rs baseline rosetta_feature_normalization_scene pins it.
include "visual.mlpl";

fn_path = if gt(list_len(args()), 0) {
  unwrap(list_get(args(), 0))
} else {
  "fixtures/feature-normalization/scene.json"
};

trace = unwrap(u:fn_read_trace("fixtures/feature-normalization/trace.json"));
scene = unwrap(u:fn_scene(trace));
text = unwrap(u:rs_write_json(fn_path, unwrap(u:rs_scene_export(scene, 4))));
print(text);
str_concat("wrote ", fn_path)
=================== demos/feature-normalization/train.mlpl
# Normalize the features position by position and write the trace the page replays: fixtures/feature-normalization/trace.json by default, or the path given as the script's argument. The JSON written is also printed; the reg-rs baseline rosetta_feature_normalization_trace pins it.
include "fn.mlpl";

fn_path = if gt(list_len(args()), 0) {
  unwrap(list_get(args(), 0))
} else {
  "fixtures/feature-normalization/trace.json"
};

text = unwrap(u:rs_write_json(fn_path, u:fn_trace(u:fn_steps(), 6)));
print(text);
str_concat("wrote ", fn_path)
=================== demos/feature-normalization/visual.mlpl
# The Visual face of feature normalization, as a line scene built from the trace. Left, three independent lanes, one per position: the feature and its mean into −, then ÷ the spread, into z, with the lane being computed lit and each z cell holding a bar once computed. Right, the index-space panel: each position maps to its triple (x, μ, σ), the one rule f is applied, and z comes out; the lanes never touch, which is what makes the computation applicative. Every edge and label carries a symbol id of the equation record. Coordinates are scene units, roughly 17 wide by 9 high.
include "../../lib/rosetta/scene.mlpl";
include "equation.mlpl";

def u:fn_palette() {
  "The RGBA colours of the face.";
  {structure: [0.78, 0.8, 0.88, 1], input: [0.4, 0.85, 0.95, 1], param: [0.95, 0.85, 0.4, 1], output: [0.72, 0.58, 0.95, 1], flow: [0.55, 0.58, 0.68, 1], lit: [1, 0.6, 0.25, 1]}
}

def u:fn_lane_y(k) {
  "Scene y of lane k.";
  7.4 - k * 2.2
}

def u:fn_lane(scene, trace, k, t) {
  "One lane: x_k and μ_k into −, ÷ σ_k, into z_k; the z cell holds a bar once position k has been computed.";
  c = u:fn_palette();
  y = u:fn_lane_y(k);
  x = take(trace.constants.x, 0, k);
  mu = take(trace.constants.mu, 0, k);
  sg = take(trace.constants.sigma, 0, k);
  z = take(take(reshape(trace.channels.z.values, trace.channels.z.shape), 0, t), 0, k);
  scene = u:rs_scene_box(scene, 1.0, y + 0.45, 1.1, 0.6, "x", to_string(x), c.input)?;
  scene = u:rs_scene_box(scene, 1.0, y - 0.45, 1.1, 0.6, "mu", to_string(mu), c.param)?;
  scene = u:rs_scene_box(scene, 2.9, y, 0.8, 0.6, "sub", "−", c.structure)?;
  scene = u:rs_scene_box(scene, 4.6, y - 0.75, 1.1, 0.6, "sigma", to_string(sg), c.param)?;
  scene = u:rs_scene_box(scene, 4.6, y, 0.8, 0.6, "div", "÷", c.structure)?;
  scene = u:rs_scene_rect(scene, 6.1, y - 0.35, 7.7, y + 0.35, "z", c.output)?;
  scene = u:rs_scene_label(scene, [8.1, y, 0], "z", "z")?;
  scene = u:rs_scene_segment(scene, 1.55, y + 0.45, 2.5, y + 0.1, "x", c.flow)?;
  scene = u:rs_scene_segment(scene, 1.55, y - 0.45, 2.5, y - 0.1, "mu", c.flow)?;
  scene = u:rs_scene_segment(scene, 3.3, y, 4.2, y, "sub", c.flow)?;
  scene = u:rs_scene_segment(scene, 4.6, y - 0.45, 4.6, y - 0.3, "sigma", c.flow)?;
  scene = u:rs_scene_segment(scene, 5.0, y, 6.1, y, "div", c.flow)?;
  unit = 0.75 / (reduce(:max, abs(trace.channels.div)) + 0.0001);
  scene = u:rs_scene_segment(scene, 6.9, y - 0.12, 6.9 + z * unit, y - 0.12, "z", c.output)?;
  scene = u:rs_scene_segment(scene, 6.9, y + 0.12, 6.9 + z * unit, y + 0.12, "z", c.output)?;
  half = if eq(k, take(trace.channels.i, 0, t)) {
    1
  } else {
    0
  };
  u:rs_scene_rect(scene, 0.35 - half * 0.1, y - 1.0 * half, 8.5 * half + 0.35 * (1 - half), y + 1.0 * half, "i", c.lit)
}

def u:fn_index_panel(scene, trace, t) {
  "The applicative view: index ──▶ triple ──f──▶ z, one row per position, the current one lit.";
  c = u:fn_palette();
  scene = u:rs_scene_label(scene, [10.2, 8.9, 0], "Fin", "Fin(3)")?;
  scene = u:rs_scene_label(scene, [12.6, 8.9, 0], "tuple", "(x, μ, σ)")?;
  scene = u:rs_scene_label(scene, [16.0, 8.9, 0], "z", "z")?;
  k = 0;
  while lt(k, 3) {
    y = u:fn_lane_y(k);
    scene = u:rs_scene_box(scene, 10.2, y, 0.7, 0.6, "i", to_string(k), c.structure)?;
    scene = u:rs_scene_segment(scene, 10.6, y, 11.4, y, "in", c.flow)?;
    scene = u:rs_scene_box(scene, 12.6, y, 2.2, 0.6, "tuple", str_concat(str_concat(str_concat(str_concat(to_string(take(trace.constants.x, 0, k)), ", "), to_string(take(trace.constants.mu, 0, k))), ", "), to_string(take(trace.constants.sigma, 0, k))), c.param)?;
    scene = u:rs_scene_segment(scene, 13.75, y, 14.3, y, "div", c.flow)?;
    scene = u:rs_scene_box(scene, 14.7, y, 0.7, 0.6, "div", "f", c.structure)?;
    scene = u:rs_scene_segment(scene, 15.1, y, 15.6, y, "div", c.flow)?;
    scene = u:rs_scene_diamond(scene, 16.0, y, 0.16, "z", c.output)?;
    k = k + 1
  };
  ok(scene)
}

def u:fn_panels(scene) {
  "Name the two panels for the page's legend and callouts.";
  c = u:fn_palette();
  scene = u:rs_scene_panel(scene, "lanes", "Lanes", "One lane per position: the feature x and its mean μ meet at −, the difference is divided by the spread σ, and z comes out as a bar in its cell. The lane being computed is outlined; the other two do not change when it runs, because no lane depends on another.", [0.2, 2.0, 8.6, 8.6], c.output)?;
  u:rs_scene_panel(scene, "index", "Index space", "The applicative view: each position of Fin(3) maps to its triple (x, μ, σ), the same rule f is applied, and a z results. A fixed 3-tuple is the same thing as a function from these three positions to numbers; that is what the tuple line on the M face declares, and why the work can run pointwise with nothing summed.", [9.6, 2.0, 16.6, 9.3], c.param)
}

def u:fn_visual(trace, t) {
  "The whole Visual face at step t of a parsed trace record.";
  scene = u:rs_scene_new(trace.axis.name);
  k = 0;
  while lt(k, 3) {
    scene = u:fn_lane(scene, trace, k, t)?;
    k = k + 1
  };
  scene = u:fn_index_panel(scene, trace, t)?;
  u:fn_panels(scene)
}

def u:fn_scene(trace) {
  "The Visual face with one frame per position.";
  scene = u:fn_visual(trace, 0)?;
  t = 0;
  while lt(t, trace.axis.count) {
    frame = u:fn_visual(trace, t)?;
    scene = u:rs_scene_frame(scene, reshape(frame.positions, [frame.vertex_count, 3]))?;
    t = t + 1
  };
  ok(scene)
}

def u:fn_read_trace(path) {
  "The trace record from its fixture.";
  parse_json(read_text(path)?)
}

