// Drive headless Chrome over the DevTools protocol: real pointer moves, then inspect the callouts.
import { spawn } from "node:child_process";
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const url = process.argv[2];
const probes = JSON.parse(process.argv[3]); // [{face, dx, dy}] fractions of the face's client rect
const port = 9333;
const proc = spawn(chrome, ["--headless=new", "--disable-gpu", "--hide-scrollbars", `--remote-debugging-port=${port}`, "--window-size=1280,1100", "about:blank"], { stdio: "ignore" });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let targets;
for (let i = 0; i < 50; i++) { try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); break; } catch { await sleep(200); } }
const page = targets.find((t) => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let id = 0; const pending = new Map();
ws.onmessage = (m) => { const d = JSON.parse(m.data); if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); } };
const send = (method, params = {}) => new Promise((r) => { const n = ++id; pending.set(n, r); ws.send(JSON.stringify({ id: n, method, params })); });
const ev = async (expr) => { const r = await send("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true }); return r.result?.result?.value ?? r.result?.exceptionDetails?.text; };
await send("Page.enable"); await send("Runtime.enable");
await send("Page.navigate", { url });
await sleep(2500);
for (const p of probes) {
  const rect = await ev(`(()=>{const f=document.querySelector('.face[data-face="${p.face}"]');const r=f.getBoundingClientRect();return {l:r.left,t:r.top,w:r.width,h:r.height}})()`);
  const x = rect.l + rect.w * p.dx, y = rect.t + rect.h * p.dy;
  // approach in a few steps like a real hand, then rest
  for (let k = 1; k <= 4; k++) { await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: x - (4 - k) * 30, y: y + (4 - k) * 10 }); await sleep(40); }
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
  await sleep(500);
  const info = await ev(`(()=>{const el=document.elementFromPoint(${x},${y});const face=el&&el.closest('.face');const boxes=[...document.querySelectorAll('.callout-box')].map(b=>({cls:b.className,l:b.style.left,t:b.style.top,title:b.querySelector('b')?.textContent}));return {target:el?el.tagName+(el.dataset?.id?'#'+el.dataset.id:'')+(el.dataset?.line!==undefined?' line'+el.dataset.line:''):null,face:face?face.dataset.face:null,hidden:document.getElementById('callout').hidden,mode:document.body.dataset.mode||null,boxes}})()`);
  console.log(JSON.stringify({ probe: p, at: [Math.round(x), Math.round(y)], rect, ...info }));
}
if (process.argv[4]) { const s = await send("Page.captureScreenshot"); (await import("node:fs")).writeFileSync(process.argv[4], Buffer.from(s.result.data, "base64")); }
ws.close(); proc.kill();
EOF
